/* ============================================
   Volta Studio — Shared Stylesheet
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400;1,500;1,600&family=Inter:wght@300;400;500;600&display=swap');

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #F5F2ED;
  --bg-alt: #EDE8E1;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --text-light: #9A9490;
  --accent-terracotta: #C67D5B;
  --accent-sage: #8B9E7E;
  --accent-sand: #D4C5A9;
  --accent-clay: #B8856C;
  --accent-olive: #7A8B6F;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1280px;
  --reading-width: 680px;
  --nav-height: 72px;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.6;
  color: var(--text);
  background-color: var(--bg);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  height: var(--nav-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 clamp(1.5rem, 4vw, 3rem);
  background-color: var(--bg);
  transition: background-color 0.3s ease;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-size: 0.9rem;
  font-weight: 400;
  color: var(--text-muted);
  transition: color 0.25s ease;
  letter-spacing: 0.01em;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 28px;
  height: 28px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 100%;
  height: 1.5px;
  background-color: var(--text);
  transition: transform 0.35s ease, opacity 0.25s ease;
  transform-origin: center;
}

.hamburger.is-active span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}

.hamburger.is-active span:nth-child(2) {
  opacity: 0;
}

.hamburger.is-active span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}

/* Mobile Overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  z-index: 150;
  background-color: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2.5rem;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.mobile-overlay.is-open {
  opacity: 1;
  visibility: visible;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 500;
  color: var(--text);
  transition: color 0.25s ease, transform 0.25s ease;
  display: block;
}

.mobile-overlay a:hover {
  color: var(--accent-terracotta);
  transform: translateX(8px);
}

/* --- Page Content Spacer --- */
.page-content {
  padding-top: var(--nav-height);
}

/* --- Hero Section --- */
.hero {
  padding: clamp(4rem, 10vw, 8rem) clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 7vw, 5.5rem);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: -0.03em;
  max-width: 900px;
  color: var(--text);
}

/* --- Media Showcase --- */
.media-showcase {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr 1fr;
  gap: clamp(0.75rem, 1.5vw, 1.25rem);
  padding: 0 clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto clamp(4rem, 8vw, 7rem);
}

.media-block {
  border-radius: 4px;
  aspect-ratio: 4 / 5;
}

.media-block:nth-child(1) {
  background-color: var(--accent-terracotta);
  aspect-ratio: 3 / 4;
}

.media-block:nth-child(2) {
  background-color: var(--accent-sage);
  aspect-ratio: 1 / 1;
  align-self: center;
}

.media-block:nth-child(3) {
  background-color: var(--accent-sand);
  aspect-ratio: 4 / 5;
}

/* --- Client Marquee --- */
.marquee-section {
  padding: clamp(2rem, 5vw, 4rem) 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  border-bottom: 1px solid rgba(26, 26, 26, 0.08);
}

.marquee-row {
  display: flex;
  width: max-content;
  margin-bottom: 1rem;
}

.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}

.marquee-row:nth-child(odd) .marquee-track {
  animation-name: marquee-left;
  animation-duration: 35s;
}

.marquee-row:nth-child(even) .marquee-track {
  animation-name: marquee-right;
  animation-duration: 40s;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 500;
  white-space: nowrap;
  padding: 0 1rem;
  color: var(--text);
  letter-spacing: -0.01em;
}

.marquee-separator {
  color: var(--text-light);
  padding: 0 0.75rem;
  font-size: clamp(0.8rem, 1.5vw, 1rem);
  opacity: 0.5;
}

/* --- About Section --- */
.about-section {
  padding: clamp(5rem, 10vw, 8rem) clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 2.5rem;
}

.about-text {
  max-width: 780px;
  font-size: clamp(1.05rem, 1.8vw, 1.2rem);
  line-height: 1.75;
  color: var(--text);
}

.about-text p {
  margin-bottom: 1.5rem;
}

.about-text p:last-child {
  margin-bottom: 0;
}

/* --- Footer --- */
.footer {
  padding: 3rem clamp(1.5rem, 4vw, 3rem);
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  text-align: center;
}

.footer-text {
  font-size: 0.8rem;
  color: var(--text-light);
  letter-spacing: 0.02em;
}

/* --- Founder Letter (Neweno) --- */
.letter-section {
  padding: clamp(4rem, 10vw, 8rem) clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.letter-heading {
  font-family: var(--font-serif);
  font-size: clamp(3.5rem, 10vw, 8rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: clamp(3rem, 6vw, 5rem);
  color: var(--text);
}

.letter-body {
  max-width: var(--reading-width);
  margin: 0 auto;
}

.letter-body p {
  font-size: clamp(1.05rem, 1.8vw, 1.15rem);
  line-height: 1.85;
  margin-bottom: 1.75rem;
  color: var(--text);
}

.letter-body p:last-child {
  margin-bottom: 0;
}

.letter-body .letter-greeting {
  font-family: var(--font-serif);
  font-size: clamp(1.3rem, 2.5vw, 1.6rem);
  font-weight: 500;
  font-style: italic;
  margin-bottom: 2.5rem;
  color: var(--text);
}

.letter-body .letter-closing {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.2rem;
  margin-top: 3rem;
  color: var(--accent-terracotta);
}

/* --- Services Page --- */
.philosophy-section {
  padding: clamp(4rem, 10vw, 8rem) clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-title {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  margin-bottom: clamp(2rem, 4vw, 3rem);
}

.philosophy-text {
  max-width: 720px;
  font-size: clamp(1.05rem, 1.8vw, 1.15rem);
  line-height: 1.8;
}

.philosophy-text p {
  margin-bottom: 1.5rem;
}

.divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 4vw, 3rem);
}

.divider hr {
  border: none;
  border-top: 1px solid rgba(26, 26, 26, 0.1);
}

.services-detail {
  padding: clamp(4rem, 8vw, 7rem) clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-question {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 600;
  font-style: italic;
  letter-spacing: -0.02em;
  margin-bottom: clamp(3rem, 6vw, 4.5rem);
  max-width: 600px;
  line-height: 1.2;
}

.service-item {
  margin-bottom: clamp(2.5rem, 5vw, 4rem);
  max-width: 720px;
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-name {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 2.5vw, 1.8rem);
  font-weight: 700;
  margin-bottom: 1rem;
}

.service-description {
  font-size: clamp(1rem, 1.5vw, 1.1rem);
  line-height: 1.8;
  color: var(--text);
}

/* --- Clients Page --- */
.clients-header {
  padding: clamp(4rem, 10vw, 8rem) clamp(1.5rem, 4vw, 3rem) clamp(2rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-title {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.clients-subtitle {
  font-family: var(--font-serif);
  font-size: clamp(1.2rem, 2vw, 1.5rem);
  font-style: italic;
  color: var(--text-muted);
  margin-top: 0.75rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  padding: 0 clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
  padding-bottom: clamp(4rem, 8vw, 7rem);
}

.client-card {
  padding: clamp(1.5rem, 3vw, 2.5rem);
  border-bottom: 1px solid rgba(26, 26, 26, 0.08);
  border-right: 1px solid rgba(26, 26, 26, 0.08);
}

.client-card:nth-child(3n) {
  border-right: none;
}

.client-card:nth-last-child(-n+3) {
  border-bottom: none;
}

.client-name {
  font-family: var(--font-serif);
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-weight: 700;
  margin-bottom: 0.6rem;
  letter-spacing: -0.01em;
}

.client-desc {
  font-size: 0.88rem;
  line-height: 1.65;
  color: var(--text-muted);
}

/* --- Contact Page --- */
.contact-section {
  min-height: calc(100vh - var(--nav-height));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: clamp(2rem, 4vw, 4rem) clamp(1.5rem, 4vw, 3rem);
  text-align: center;
}

.contact-heading {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 16rem);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 0.9;
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
  color: var(--text);
}

.contact-links {
  display: flex;
  gap: clamp(1.5rem, 3vw, 3rem);
  flex-wrap: wrap;
  justify-content: center;
}

.contact-link {
  font-family: var(--font-serif);
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-weight: 400;
  color: var(--text-muted);
  transition: color 0.25s ease;
  position: relative;
}

.contact-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--text);
  transition: width 0.35s ease;
}

.contact-link:hover {
  color: var(--text);
}

.contact-link:hover::after {
  width: 100%;
}

/* --- Responsive --- */
@media (max-width: 900px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .client-card:nth-child(3n) {
    border-right: 1px solid rgba(26, 26, 26, 0.08);
  }

  .client-card:nth-child(2n) {
    border-right: none;
  }

  .client-card:nth-last-child(-n+3) {
    border-bottom: 1px solid rgba(26, 26, 26, 0.08);
  }

  .client-card:nth-last-child(-n+2) {
    border-bottom: none;
  }

  .media-showcase {
    grid-template-columns: 1fr 1fr;
  }

  .media-block:nth-child(3) {
    display: none;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero-title {
    font-size: clamp(2.2rem, 9vw, 3.5rem);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .media-block:nth-child(3) {
    display: block;
  }

  .media-block {
    aspect-ratio: 16 / 10 !important;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }

  .client-card {
    border-right: none !important;
  }

  .client-card:nth-last-child(-n+3) {
    border-bottom: 1px solid rgba(26, 26, 26, 0.08);
  }

  .client-card:last-child {
    border-bottom: none;
  }

  .contact-heading {
    font-size: clamp(3.5rem, 20vw, 8rem);
  }

  .contact-links {
    flex-direction: column;
    align-items: center;
    gap: 1.25rem;
  }

  .letter-heading {
    font-size: clamp(2.5rem, 12vw, 5rem);
  }
}

/* --- Page entrance animation --- */
@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-in {
  animation: fade-up 0.8s ease-out both;
}

.animate-in-delay-1 { animation-delay: 0.15s; }
.animate-in-delay-2 { animation-delay: 0.3s; }
.animate-in-delay-3 { animation-delay: 0.45s; }

