.mobile-overlay {
  position: fixed;
  inset: 0;
  z-index: 150;
  background-color: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2.5rem;
  opacity: 0;
  visibility: hidden;
