  font-size: clamp(0.8rem, 1.5vw, 1rem);
  opacity: 0.5;
}

/* --- About Section --- */
.about-section {
  padding: clamp(5rem, 10vw, 8rem) clamp(1.5rem, 4vw, 3rem);
  max-width: var(--max-width);
  margin: 0 auto;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
